<?php require '../config/database.php';auth();$rows=$pdo->query("SELECT r.*,c.name customer,t.name technician FROM repairs r JOIN customers c ON c.id=r.customer_id LEFT JOIN technicians t ON t.id=r.technician_id ORDER BY r.id DESC")->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>طلبات الصيانة</h1><a class="btn" href="add.php">فتح طلب صيانة</a><table><tr><th>#</th><th>العميل</th><th>الجهاز</th><th>الفني</th><th>الحالة</th><th>التكلفة</th><th>الإجراء</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=htmlspecialchars($r['customer'])?></td><td><?=htmlspecialchars($r['device_type'].' '.$r['device_model'])?></td><td><?=htmlspecialchars($r['technician']??'غير محدد')?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=$r['final_cost']?></td><td><a href="view.php?id=<?=$r['id']?>">عرض</a> | <a href="edit.php?id=<?=$r['id']?>">تعديل</a></td></tr><?php endforeach;?></table></main>
